public Object solve(){
    int N = in.it();
    String[] SS = in.str(N);

    a:for (int i = 0;i < N;i++)
      for (int j = 0;j < N;j++) {
        if (i == j)
          continue;
        if (SS[i].contains(SS[j])) {
          SS[j] = SS[N -1];
          N--;
          i = -1; // Reset loop counter to ensure outer loop runs correctly
          continue a;
        }
      }

    char[][] S = new char[N][];
    for (int i = 0;i < N;i++)
      S[i] = SS[i].toCharArray();
    RollingHash[] rhs = new RollingHash[N];
    for (int i = 0;i < N;i++)
      rhs[i] = new RollingHash(S[i],false);
    int[][] E = new int[N][N];
    for (int i = 0;i < N;i++)
      for (int j = 0;j < N;j++)
        for (int l = 1;l <= min(S[i].length,S[j].length);l++)
          if (rhs[i].get(S[i].length -l,S[i].length) == rhs[j].get(0,l))
            E[i][j] = l;

    long[][] dp = new long[1 <<N][N];

    for (int bit = 0;bit < 1 <<N;bit++)
      for (int i = 0;i < N;i++)
        for (int j = 0;j < N;j++) {
          if ((bit >>i &1) == 0 || (bit >>j &1) == 1)
            continue;
          dp[bit |1 <<j][j] = max(dp[bit |1 <<j][j],dp[bit][i] +E[i][j]);
        }
    long sum = 0;
    for (var s:S)
      sum += s.length;

    long ans = infL;
    for (int i = 0;i < N;i++)
      ans = min(ans,sum -dp[(1 <<N) -1][i]);
    return ans;
  }
